// Generated by scripts/optimize-images.js — tiny base64 previews shown
// while the full image loads. Re-run the script after changing photos.
export const blurDataUrls: Record<string, string> = {
  "/photos/hero.jpg": "data:image/jpeg;base64,",
  "/photos/automotive.jpg": "data:image/jpeg;base64,",
  "/photos/boxes.jpg": "data:image/jpeg;base64,"
};

export const blurFor = (src: string) => blurDataUrls[src];
